```python
"""Data models for the warehouse inventory system.

Each model is a dataclass that round-trips through plain dictionaries via
``to_dict()`` / ``from_dict()`` so instances can be stored as JSON.
"""

from dataclasses import asdict, dataclass
from typing import Any, Dict, Optional

__all__ = ["Product", "Location", "StockLevel", "Movement"]


@dataclass
class Product:
    """A product identified by its SKU."""

    sku: str
    name: str
    unit_cost: float
    reorder_point: int

    def to_dict(self) -> Dict[str, Any]:
        """Return the plain-dict representation used on disk."""
        return asdict(self)

    @classmethod
    def from_dict(cls, d: Dict[str, Any]) -> "Product":
        """Rebuild a :class:`Product` from :meth:`to_dict` output."""
        return cls(
            sku=d["sku"],
            name=d["name"],
            unit_cost=d["unit_cost"],
            reorder_point=d["reorder_point"],
        )


@dataclass
class Location:
    """A storage location with a maximum total capacity across all skus."""

    code: str
    capacity: int

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)

    @classmethod
    def from_dict(cls, d: Dict[str, Any]) -> "Location":
        return cls(code=d["code"], capacity=d["capacity"])


@dataclass
class StockLevel:
    """Quantity of one sku currently held at one location."""

    sku: str
    location_code: str
    quantity: int

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)

    @classmethod
    def from_dict(cls, d: Dict[str, Any]) -> "StockLevel":
        return cls(sku=d["sku"], location_code=d["location_code"], quantity=d["quantity"])


@dataclass
class Movement:
    """One ledger entry.

    ``kind`` is one of ``'receive'``, ``'ship'``, ``'transfer'`` or
    ``'adjust'``.  For adjustments, ``qty`` holds the signed delta and ``src``
    holds the adjusted location (``dst`` is ``None``).
    """

    kind: str
    sku: str
    qty: int
    src: Optional[str]
    dst: Optional[str]
    ts: int
    ref: str

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)

    @classmethod
    def from_dict(cls, d: Dict[str, Any]) -> "Movement":
        return cls(
            kind=d["kind"],
            sku=d["sku"],
            qty=d["qty"],
            src=d["src"],
            dst=d["dst"],
            ts=d["ts"],
            ref=d["ref"],
        )
